-- =============================================================================
-- Migration: 0007_relief_alerts.sql
-- Description: Emergency water relief rationing queues, tanker dispatches, and SMS subscriptions
-- Tables: relief_requests, relief_dispatches, sms_subscriptions, sms_delivery_logs
-- Rules Enforced:
--   WR10: 48-Hour continuous dry zone relief priority
--   WR11: Closed-loop dispatch verification (recipient sign-off required)
-- =============================================================================

-- 1. Emergency Relief Requests Table (Generated by barangay officials or automated triggers)
CREATE TABLE IF NOT EXISTS public.relief_requests (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    cluster_id UUID REFERENCES public.report_clusters(id) ON DELETE SET NULL,
    barangay_id UUID NOT NULL REFERENCES public.barangays(id) ON DELETE RESTRICT,
    requested_by UUID REFERENCES public.profiles(id) ON DELETE SET NULL,
    urgency TEXT NOT NULL DEFAULT 'standard' CHECK (urgency IN ('standard', 'elevated', 'critical')),
    consecutive_dry_hours NUMERIC(5,2) DEFAULT 0.00,
    status TEXT NOT NULL DEFAULT 'pending' CHECK (status IN ('pending', 'approved', 'dispatched', 'fulfilled', 'cancelled')),
    notes TEXT,
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

CREATE INDEX IF NOT EXISTS idx_relief_requests_barangay_id
    ON public.relief_requests(barangay_id);

CREATE INDEX IF NOT EXISTS idx_relief_requests_status_urgency
    ON public.relief_requests(status, urgency);


-- 2. Water Relief Dispatches Table (CDRRMO Tanker Fleet Lifecycle)
CREATE TABLE IF NOT EXISTS public.relief_dispatches (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    request_id UUID REFERENCES public.relief_requests(id) ON DELETE SET NULL,
    barangay_id UUID NOT NULL REFERENCES public.barangays(id) ON DELETE RESTRICT,
    tanker_plate_number TEXT NOT NULL,
    driver_name TEXT NOT NULL,
    capacity_liters INT NOT NULL DEFAULT 10000,
    dispatched_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    arrived_at TIMESTAMPTZ,
    completed_at TIMESTAMPTZ,
    status TEXT NOT NULL DEFAULT 'queued' CHECK (status IN ('queued', 'in_transit', 'on_site', 'completed', 'cancelled')),
    recipient_acknowledgment TEXT, -- Rule WR11: Closed-loop verification signature or OTP
    dispatched_by UUID REFERENCES public.profiles(id) ON DELETE SET NULL,
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

CREATE INDEX IF NOT EXISTS idx_relief_dispatches_status
    ON public.relief_dispatches(status);

CREATE INDEX IF NOT EXISTS idx_relief_dispatches_barangay_id
    ON public.relief_dispatches(barangay_id);


-- 3. SMS Alert Subscriptions Table (Encrypted phone storage with opt-in consent)
CREATE TABLE IF NOT EXISTS public.sms_subscriptions (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    mobile_encrypted TEXT NOT NULL,
    barangay_id UUID NOT NULL REFERENCES public.barangays(id) ON DELETE CASCADE,
    is_verified BOOLEAN NOT NULL DEFAULT FALSE,
    subscribed_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    unsubscribed_at TIMESTAMPTZ
);

CREATE INDEX IF NOT EXISTS idx_sms_subscriptions_barangay
    ON public.sms_subscriptions(barangay_id)
    WHERE unsubscribed_at IS NULL;


-- 4. SMS Delivery Logs Table
CREATE TABLE IF NOT EXISTS public.sms_delivery_logs (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    subscription_id UUID REFERENCES public.sms_subscriptions(id) ON DELETE SET NULL,
    message_body TEXT NOT NULL,
    status TEXT NOT NULL DEFAULT 'sent',
    error_message TEXT,
    sent_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

CREATE INDEX IF NOT EXISTS idx_sms_delivery_logs_sent_at
    ON public.sms_delivery_logs(sent_at DESC);


-- -----------------------------------------------------------------------------
-- ROW-LEVEL SECURITY & ACCESS POLICIES
-- -----------------------------------------------------------------------------

ALTER TABLE public.relief_requests ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.relief_dispatches ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.sms_subscriptions ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.sms_delivery_logs ENABLE ROW LEVEL SECURITY;

-- Relief Requests Policies:
-- Barangay officials can view and create requests for their assigned barangay
CREATE POLICY "Barangay officials can view assigned relief requests"
    ON public.relief_requests FOR SELECT
    TO authenticated
    USING (
        (public.app_role() = 'barangay_official' AND barangay_id = public.app_barangay())
        OR public.app_role() IN ('lgu_dispatcher', 'admin', 'auditor')
    );

CREATE POLICY "Barangay officials can create relief requests"
    ON public.relief_requests FOR INSERT
    TO authenticated
    WITH CHECK (
        (public.app_role() = 'barangay_official' AND barangay_id = public.app_barangay())
        OR public.app_role() IN ('lgu_dispatcher', 'admin')
    );

CREATE POLICY "Dispatchers and admins can update relief requests"
    ON public.relief_requests FOR UPDATE
    TO authenticated
    USING (public.app_role() IN ('lgu_dispatcher', 'admin'))
    WITH CHECK (public.app_role() IN ('lgu_dispatcher', 'admin'));

-- Relief Dispatches Policies:
-- Public can view active dispatches without driver personal details (views handle redaction)
CREATE POLICY "Staff can view relief dispatches"
    ON public.relief_dispatches FOR SELECT
    TO authenticated
    USING (
        public.app_role() IN ('lgu_dispatcher', 'admin', 'auditor')
        OR (public.app_role() = 'barangay_official' AND barangay_id = public.app_barangay())
    );

CREATE POLICY "Dispatchers and admins can manage relief dispatches"
    ON public.relief_dispatches FOR ALL
    TO authenticated
    USING (public.app_role() IN ('lgu_dispatcher', 'admin'))
    WITH CHECK (public.app_role() IN ('lgu_dispatcher', 'admin'));

-- SMS Subscriptions & Logs Policies:
CREATE POLICY "Users can manage own subscriptions via edge service"
    ON public.sms_subscriptions FOR ALL
    TO authenticated
    USING (public.app_role() = 'admin')
    WITH CHECK (public.app_role() = 'admin');

CREATE POLICY "Admins can view sms logs"
    ON public.sms_delivery_logs FOR SELECT
    TO authenticated
    USING (public.app_role() = 'admin');

